import { test, expect } from '@playwright/test';

test.describe('Edit Existing Task Functionality', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/tasks');
  });

  test('should successfully edit an existing task by clicking Edit button', async ({ page }) => {
    // Verify task list is visible
    const taskList = page.getByRole('list');
    await expect(taskList).toBeVisible();

    // Locate and click Edit button for the first task
    const editButton = page.getByRole('button', { name: /edit/i }).first();
    await expect(editButton).toBeVisible();
    await editButton.click();

    // Verify edit modal is displayed
    const editModal = page.getByRole('dialog', { name: /edit task/i });
    await expect(editModal).toBeVisible();

    // Verify task title is pre-filled
    const titleInput = page.getByLabel(/task title/i);
    await expect(titleInput).toHaveValue('Complete the Playwright script');

    // Verify task description is pre-filled
    const descriptionInput = page.getByLabel(/task description/i);
    await expect(descriptionInput).toHaveValue('Generate a production-quality Playwright script');

    // Update task title
    await titleInput.fill('Refactor Playwright script');

    // Click Save button
    const saveButton = page.getByRole('button', { name: /save/i });
    await expect(saveButton).toBeVisible();
    await saveButton.click();

    // Verify success message appears
    const successMessage = page.getByText(/task updated successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify modal closes
    await expect(editModal).not.toBeVisible();

    // Verify updated title is displayed in task list
    const updatedTaskTitle = page.getByText('Refactor Playwright script');
    await expect(updatedTaskTitle).toBeVisible();
  });

  test('should handle validation when attempting to save an empty task title', async ({ page }) => {
    // Locate and click Edit button for the second task
    const editButton = page.getByRole('button', { name: /edit/i }).nth(1);
    await expect(editButton).toBeVisible();
    await editButton.click();

    // Verify edit modal is displayed
    const editModal = page.getByRole('dialog', { name: /edit task/i });
    await expect(editModal).toBeVisible();

    // Clear task title input
    const titleInput = page.getByLabel(/task title/i);
    await titleInput.clear();

    // Verify validation error appears
    const validationError = page.getByText(/task title is required/i);
    await expect(validationError).not.toBeVisible();

    // Click Save button with empty title
    const saveButton = page.getByRole('button', { name: /save/i });
    await saveButton.click();

    // Verify validation error is displayed
    await expect(validationError).toBeVisible();

    // Verify modal remains open
    await expect(editModal).toBeVisible();

    // Verify task title input still has empty value
    await expect(titleInput).toHaveValue('');

    // Verify task was not updated
    const originalTitle = page.getByText('Complete the Playwright script');
    await expect(originalTitle).toBeVisible();
  });
});
